INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64897541', 64897541, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Pembangunan Wilayah dan Strategi Pendanaan, Unit Kerja Staf Ahli Bidang Inovasi Pendanaan Pembangunan Tahun Anggaran 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 125000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Rencana Pembangunan Jangka Menengah Nasional (RPJMN) Tahun 2025–2029 disusun sebagai dokumen perencanaan strategis lima tahunan yang menjadi pedoman pelaksanaan pembangunan nasional dalam rangka mencapai visi Indonesia Emas 2045. Dalam RPJMN 2025– 2029 menetapkan sejumlah proyek prioritas dalam agenda pembangunan dan Proyek Strategis Nasional (PSN) untuk mewujudkan visi Indonesia Emas 2045. Pendanaan pembangunan dalam RPJMN 2025-2029 diarahkan untuk tidak hanya mengandalkan sumber pendanaan dari Anggaran Pendapatan dan Belanja Negara (APBN) atau Anggaran Pendapatan dan Belanja Daerah (APBD), tetapi juga memperluas peran pendanaan non-pemerintah melalui mobilisasi investasi swasta, BUMN, serta partisipasi masyarakat.', 'Konsultan Analis Pembangunan Wilayah dan Strategi Pendanaan bertanggung jawab terhadap pelaksanaan Kajian Inovasi Pendanaan Pembangunan Proyek Prioritas dan Strategis Nasional dalam RPJMN 2025-2029 Bidang Pembangunan Wilayah antara lain: 1) Identifikasi potensi ekonomi dan kewilayahan dengan melakukan pemetaan potensi ekonomi, sosial, dan infrastruktur dasar di wilayah studi terpilih; 2) Analisis potensi dan tantangan pembangunan wilayah dengan analisis SWOT terhadap isu strategis pembangunan di wilayah studi terpilih; 3) Identifikasi potensi dan strategi pendanaan melalui kerangka skema pendanaan inovatif dan kolaborasi multipihak di wilayah studi terpilih; 4) Analisis indikasi risiko yang berpotensi muncul dalam implementasi kegiatan serta merumuskan strategi pengelolaan risiko di wilayah studi terpilih; 5) Analisis kelembagaan dengan melakukan analisis pemetaan stakeholder di tingkat pusat dan daerah, swasta, dan pihak lain yang mendukung kegiatan di wilayah studi terpilih; 6) Perumusan rekomendasi kebijakan dan strategi pendanaan inovatif pada kegiatan di wilayah studi terpilih.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1834967);
