INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64898311', 64898311, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pendidikan', 'Pembangunan Ruang UKS SMAN 2 Bandar', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Sumatera Utara, Simalungun (Kab.)', 150660000, 'February 2026', 'APBD', 1, 1, '1 paket', 'Pembangunan Ruang UKS SMAN 2 Bandar', 'Ruang lingkup pekerjaan Konstruksi utama terdiri dari: 1. Melakukan pemeriksaan dan penilaian dokumen untuk pelaksanaan konstruksi fisik, baik dari segi kelengkapan maupun segi kebenarannya. 2. Menyusun program kerja yang meliputi jadwal waktu pelaksanaan, jadwal pengadaan bahan, jadwal penggunaan tenaga kerja, dan jadwal penggunaan peralatan berat. 3. Melaksanakan persiapan di lapangan sesuai dengan pedoman pelaksanaan. 4. Menyusun gambar pelaksanaan (shop drawing) untuk pekerjaan-pekerjaan yang memerlukannya. 5. Melaksanakan pekerjaan konstruksi fisik di lapangan sesuai dengan dokumen pelaksanaan. 6. Melaksanakan pelaporan pelaksanaan konstruksi fisik, melalui rapat-rapat lapangan, laporan harian, laporan mingguan, laporan bulanan, laporan kemajuan pekerjaan, laporan persoalan yang timbul atau dihadapi, dan surat-menyurat. 7. Membuat gambar yang sesuai dengan pelaksanaan di lapangan (as built drawing) yang selesai sebelum serah terima pertama, setelah disetujui oleh penyedia jasa konsultansi pengawasan konstruksi dan diketahui oleh penyedia jasa konsultansi perencanaan konstruksi. 8. Melaksanakan perbaikan kerusakan-kerusakan yang terjadi di masa pemeliharaan konstruksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1835993);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64897945', 64897945, 'analyze_legacy', 'Kab. Mimika', 'kabkota', 'Dinas Pemuda dan Olahraga', 'Pemeliharaan Bangunan Gedung-Bangunan Gedung Tempat Kerja-Bangunan Gedung Kantor', 'Barang', 'Pengadaan Langsung', 'Papua Tengah, Mimika (Kab.)', 60000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Pemeliharaan Bangunan Gedung-Bangunan Gedung Tempat Kerja-Bangunan Gedung Kantor;', 'Pengadaan Ring basket;', 60000000, 'high', 'Terdapat ketidaksesuaian yang kuat antara uraian pemeliharaan gedung kantor dan spesifikasi pengadaan ring basket. Barang tersebut tidak tampak relevan dengan kebutuhan pemeliharaan bangunan gedung tempat kerja/kantor, sehingga seluruh nilai pengadaan patut dicermati sebagai potensi pemborosan atau salah klasifikasi belanja.', NULL, NULL, 3, 1, 1, 1, 1, 1835994);
