INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64899549', 64899549, 'analyze_legacy', 'Kota Malang', 'kabkota', 'Bagian Umum', 'Belanja Jasa Tenaga Keamanan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 246375000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Paket pekerjaan ini merupakan pengadaan jasa tenaga pendukung keamanan dari pihak ketiga untuk mendukung rasa aman dan kenyamanan pimpinan dalam menjalankan aktivitas kedinasan. Jasa yang disediakan meliputi penugasan tenaga yang membantu menjaga ketertiban dan situasi lingkungan di sekitar pimpinan, baik di dalam kantor maupun pada kegiatan pendukung lainnya sesuai kebutuhan unit kerja.', '1. Penyedia wajib menyediakan tenaga pendukung keamanan yang sehat jasmani dan rohani, disiplin, dan mampu melaksanakan tugas pendukung ketertiban dan kenyamanan pimpinan 2. Tenaga pendukung keamanan bekerja sesuai jadwal dan jam kerja yang ditetapkan oleh pengguna jasa 3. Pelaksanaan pekerjaan mengikuti ketentuan dan tata tertib yang berlaku di lingkungan kerja pengguna jasa 4. Penyedia bertanggung jawab atas pengawasan, pengaturan tenaga kerja, dan kualitas layanan yang diberikan.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 1839250);
